const row = $('Select Window').first().json || {};
const items = Array.isArray(row.items) ? row.items : [];
const itemCount = Number(row.item_count != null ? row.item_count : items.length);
const nowIso = new Date().toISOString();

// Attribution allow-list: a kid can be named SOLO only if at least one item is exclusively theirs.
const allowedSolo = [];
if (items.some(it => (it.student || '').toLowerCase() === 'ronin')) allowedSolo.push('Ronin');
if (items.some(it => (it.student || '').toLowerCase() === 'rory'))  allowedSolo.push('Rory');
const anyBoth = items.some(it => (it.student || '').toLowerCase() === 'both');
const jointAllowed = anyBoth || allowedSolo.length === 2;

const sys = `You write ONLY the "lead" of a daily kitchen-board summary — the warm tone-setting opener. 2-3 short sentences as plain markdown. Dates, deadlines, and times are shown by the renderer in a separate structured panel BELOW your text. Your job is the MOOD, not the calendar.

ABSOLUTE OUTPUT RULES — any violation discards the output:
- NO dates of any form. No "May 29", no "2026-06-01", no "5/29", no "the 5th of August".
- NO day-of-week names: Monday Tuesday Wednesday Thursday Friday Saturday Sunday (and abbreviations Mon/Tue/Wed/Thu/Fri/Sat/Sun).
- NO month names: January…December (or Jan…Dec).
- NO "today", "tomorrow", "yesterday".
- NO clock times: no "7 AM", no "3:30 pm".
- NO gendered pronouns: he, him, his, himself, she, her, hers, herself are FORBIDDEN. Use names or singular they/their/them.
- NO invented facts, amounts, or fees.

ATTRIBUTION RULE (anti-drift): you may mention a kid by NAME only as allowed:
- "NAMES YOU MAY MENTION SOLO" below lists names that may appear alone (e.g. "Ronin is …").
- "JOINT MENTION ALLOWED" controls whether you may write "Ronin and Rory" / "both kids".
- If a name is NOT in the solo list AND joint mention is the only option, refer to that kid only as part of "both kids" / "the family" / "Ronin and Rory together" — NEVER single them out.
- If neither solo nor joint mention is allowed, do NOT use any kid's name; refer to "the family" or "the household".
- NEVER attribute a school/system event (principal news, the school community, holidays, system updates) to a specific kid unless an item has that kid as its exclusive student.

Allowed mood words: "soon", "upcoming", "this week", "recently", "incoming", "the rhythm", "right now".`;

const userMsg = `Current time: ${nowIso}
Items in window: ${itemCount}

NAMES YOU MAY MENTION SOLO: ${allowedSolo.length ? allowedSolo.join(', ') : '(none)'}
JOINT MENTION ALLOWED: ${jointAllowed ? 'yes — you may say "both kids" or "Ronin and Rory"' : 'no'}

ITEMS (JSON — for tone, not transcription):
${JSON.stringify(items, null, 2)}

Write ONLY the lead (2-3 sentences). The renderer shows dated highlights separately — do NOT include any date, time, day-of-week, month, or clock value in your output.`;

return [{ json: {
  model: 'qwen3.6-35b', temperature: 0.2, max_tokens: 220,
  messages: [
    { role: 'system', content: sys },
    { role: 'user', content: userMsg }
  ],
  _meta: {
    item_count: itemCount,
    window: 'last 24h received + upcoming 7d due',
    as_of: nowIso,
    allowed_solo: allowedSolo,
    joint_allowed: jointAllowed
  }
}}];

const lead = (($('Validate Digest').first().json) || {}).content || '';
const items = ($('Select Window').first().json || {}).items || [];
const meta = (($('Build Prompt').first().json) || {})._meta || {};

function fmtWhen(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d)) return null;
  const utcMid = d.getUTCHours()===0 && d.getUTCMinutes()===0 && d.getUTCSeconds()===0;
  const tz = utcMid ? 'UTC' : 'America/New_York';
  const dow = new Intl.DateTimeFormat('en-US', {timeZone:tz, weekday:'long'}).format(d);
  const mon = new Intl.DateTimeFormat('en-US', {timeZone:tz, month:'long'}).format(d);
  const day = Number(new Intl.DateTimeFormat('en-CA', {timeZone:tz, day:'2-digit'}).format(d));
  if (utcMid) return `${dow}, ${mon} ${day}`;
  const time = new Intl.DateTimeFormat('en-US', {timeZone:tz, hour:'numeric', minute:'2-digit'}).format(d);
  return `${dow}, ${mon} ${day} at ${time}`;
}

const now = new Date();
const horizon = new Date(now.getTime() + 7*24*60*60*1000);
const pastFloor = new Date(now.getTime() - 24*60*60*1000);
const highlights = items
  .filter(it => it.due_at)
  .map(it => ({
    item_id: it.id,
    title: it.title,
    type: it.type,
    due_at: it.due_at,
    when_human: fmtWhen(it.due_at),
    student: it.student || 'unknown',
    action_required: !!it.action_required,
    amount: it.amount || null,
    teacher: it.teacher || null,
    course: it.course || null,
    action_url: it.action_url || null,
    action_target: it.action_target || null
  }))
  .filter(h => {
    const d = new Date(h.due_at);
    return d >= pastFloor && d <= horizon;
  })
  .sort((a,b) => new Date(a.due_at) - new Date(b.due_at))
  .slice(0, 8);

// Build a legacy `body` for clients still consuming markdown: lead + bullet list of highlights.
let bodyLegacy = lead || 'No summary.';
if (highlights.length) {
  const lines = highlights.slice(0,5).map(h => `- **${h.when_human}** — ${h.title}${h.action_required ? ' (action needed)' : ''}`);
  bodyLegacy += '\n\n' + lines.join('\n');
}

return [{ json: {
  as_of: meta.as_of,
  lead: lead || 'Nothing pressing today.',
  highlights: highlights,
  body: bodyLegacy,
  item_count: Number(meta.item_count || 0),
  time_window: meta.window || 'last 24h received + upcoming 7d due',
  model: 'qwen3.6-35b',
  prompt_version: 'v7-action-fields'
}}];

const llm = $('LiteLLM Digest').first().json || {};
const choice = (llm.choices && llm.choices[0]) || {};
const content = String((choice.message && choice.message.content) || '').trim();
const meta = (($('Build Prompt').first().json) || {})._meta || {};
const allowedSolo = new Set(meta.allowed_solo || []);
const jointAllowed = !!meta.joint_allowed;

const banned = [];

// dates/times/days
const datePatterns = [
  { name:'month-day', re:/\b(?:January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*(?:\s+\d{1,2})?\b/gi },
  { name:'day-of-week', re:/\b(?:Sunday|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sun|Mon|Tue|Tues|Wed|Thu|Thurs|Fri|Sat)\b/g },
  { name:'iso-date', re:/\b\d{4}-\d{2}-\d{2}\b/g },
  { name:'us-date',  re:/\b\d{1,2}\/\d{1,2}(?:\/\d{2,4})?\b/g },
  { name:'clock',    re:/\b\d{1,2}(?::\d{2})?\s*(?:AM|PM|am|pm|a\.m\.|p\.m\.)\b/g },
  { name:'today-tomorrow', re:/\b(?:today|tomorrow|yesterday)\b/gi }
];
for (const { name, re } of datePatterns) {
  const hits = [...content.matchAll(re)].map(m => m[0]);
  if (hits.length) banned.push(`${name}: ${JSON.stringify([...new Set(hits)])}`);
}

// gendered pronouns
const pronouns = [...content.matchAll(/\b(?:he|him|his|himself|she|her|hers|herself)\b/gi)].map(m => m[0]);
if (pronouns.length) banned.push(`pronouns: ${JSON.stringify([...new Set(pronouns)])}`);

// attribution: detect SOLO mentions by neutralizing joint phrases first
let normalized = content
  .replace(/\bRonin and Rory\b/gi, 'BOTH_KIDS')
  .replace(/\bRory and Ronin\b/gi, 'BOTH_KIDS')
  .replace(/\bboth kids\b/gi, 'BOTH_KIDS')
  .replace(/\bboth of them\b/gi, 'BOTH_KIDS');
const soloRonin = /\bRonin\b/.test(normalized);
const soloRory  = /\bRory\b/.test(normalized);

const nameIssues = [];
if (soloRonin && !allowedSolo.has('Ronin')) nameIssues.push('Ronin (no ronin-specific item)');
if (soloRory  && !allowedSolo.has('Rory'))  nameIssues.push('Rory (no rory-specific item)');
const wroteJoint = /BOTH_KIDS/.test(normalized);
if (wroteJoint && !jointAllowed) nameIssues.push('joint mention used but not allowed');
if (nameIssues.length) banned.push(`attribution: ${JSON.stringify(nameIssues)}`);

if (banned.length) {
  throw new Error(`Lead validation failed — ${banned.join(' | ')}. Body preview: ${content.slice(0, 240)}`);
}

return [{ json: { content, validation: 'ok' } }];
